// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address other, uint256 otherAmt) public {
        // Limit other to valid transfer recipients (non-zero) and amount to something reasonable
        vm.assume(other != address(0));
        vm.assume(other != owner);
        vm.assume(otherAmt > 0);

        // Make owner the actual owner
        vm.prank(owner);
        c.NETM();

        // Record initial total supply
        uint256 totalSupply = c.totalSupply();

        // Give some tokens to 'other' so we can test multi-holder sum
        vm.prank(owner);
        c.transfer(other, otherAmt);

        // Sum of known balances: owner + other
        uint256 sumBalances = c.balanceOf(owner) + c.balanceOf(other);

        // The invariant: totalSupply == sum of all balances
        // Since we only own and other have balances, the invariant must hold across all known holders.
        // To make it truly general we could also iterate, but for the given two addresses it's enough
        // to show the mutant breaks the relation.
        assertTrue(totalSupply == c.balanceOf(owner) + c.balanceOf(other));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address otherAccount) public {
        vm.assume(caller != address(0) && otherAccount != address(0) && caller != otherAccount);
        vm.prank(caller);
        c.NETM();
        uint256 sumBalances = c.balanceOf(caller) + c.balanceOf(otherAccount);
        assertTrue(sumBalances >= c.totalDistributed());
    }
}
